<script setup>import {Link} from '@inertiajs/vue3';defineProps({rows:Array})</script><template><div class="card overflow-hidden"><div class="overflow-x-auto"><table class="w-full min-w-170 text-left"><thead><tr class="border-b border-black/5 text-[11px] uppercase tracking-widest text-[#7c8b83] dark:border-white/10"><th class="px-6 py-4">Rank</th><th class="px-4 py-4">Manager & team</th><th class="px-4 py-4 text-right">GW</th><th class="px-4 py-4 text-right">Total</th><th class="px-6 py-4 text-right">Move</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id" class="border-b border-black/5 last:border-0 dark:border-white/6"><td class="px-6 py-5 text-lg font-black">{{r.league_rank}}</td><td class="px-4"><Link :href="`/managers/${r.entry.id}`" class="font-bold hover:text-[#1d7650]">{{r.entry.manager_name}}</Link><span class="block text-xs text-[#7c8b83]">{{r.entry.team_name}}</span></td><td class="px-4 text-right font-semibold">{{r.points}}</td><td class="px-4 text-right text-lg font-black">{{r.total_points}}</td><td class="px-6 text-right"><span v-if="r.previous_rank&&r.previous_rank!==r.league_rank" :class="r.previous_rank>r.league_rank?'text-emerald-600':'text-red-500'">{{r.previous_rank>r.league_rank?'↑':'↓'}} {{Math.abs(r.previous_rank-r.league_rank)}}</span><span v-else class="text-[#9aa69f]">—</span></td></tr></tbody></table></div></div></template>
